'use strict';

/**
* Method which return the default option.
*
* @private
* @name defaults
* @returns {Object} - out
*/
function defaults( ) {
	var out = {};

	// Boolean indicating whether to automatically re-render on a `change` event:
	out.autoRender = false;

	// Data which need to plot on axis
	out.axisData = void 0;

	// Default background color code
	out.backgroundColor = 'Bwhite';

	// Default foreground color code
	out.foregroundColor = 'Fblack';

	// Default glyph code
	out.glyph = 'space';

	// Default horizontel tics glyph
	out.horizontalTicsGlyph = 'HorTic';

	// Default plot area height
	out.plotAreaHeight = 15;

	// Default plot area height
	out.plotAreaWidth = 80;

	// Default vertical tics glyph
	out.verticalTicsGlyph = 'VerTic';

	// Boolean indicate weather to draw a frame
	out.drawFrame = true;

	// Axis stride
	out.ticsStride = [ 1, 1, 1, 1 ];

	// Label formate
	out.labelFormate = [ '%s', '%s', '%s', '%s' ];

	// Axis Data
	out.axisData = [ [], [], [], [] ];

	// Axis data obj
	out.axisDataObj = [
		// X
		{
			'data': [],
			'labelFormate': '%s',
			'axis': false,
			'stride': 1
		},

		// Y
		{
			'data': [],
			'labelFormate': '%s',
			'axis': false,
			'stride': 1
		},

		// Z
		{
			'data': [],
			'labelFormate': '%s',
			'axis': false,
			'stride': 1
		},

		// W
		{
			'data': [],
			'labelFormate': '%s',
			'axis': false,
			'stride': 1
		}
	];
	return out;
}

module.exports = defaults;
